import json
import sys
import re
import os
import logging
from datetime import datetime

def validate_json(values_path):
    try:
        with open(values_path, 'r', encoding='utf-8') as f:
            values = json.load(f)
    except (json.JSONDecodeError, IOError) as e:
        return False, f"Failed to read or parse JSON: {str(e)}"
    if not isinstance(values, dict):
        return False, "JSON is not an object"
    for value in values.values():
        if not isinstance(value, (int, float)):
            return False, f"Non-numeric value found: {value}"
    return True, values

def evaluate_expression(expr, values):
    try:
        # Replace variable names with their values
        for key in values:
            expr = expr.replace(key, str(values[key]))
        # Evaluate the expression safely
        result = eval(expr)
        if not isinstance(result, (int, float)):
            return None, "Expression did not evaluate to a number"
        return round(result, 2)
    except Exception as e:
        return None, f"Expression evaluation failed: {str(e)}"

def render_template(template_path, values):
    try:
        with open(template_path, 'r', encoding='utf-8') as f:
            template = f.read()
    except IOError as e:
        return None, f"Failed to read template: {str(e)}"

    def replace_key(match):
        key = match.group(1)
        if key not in values:
            return f"ERROR: Key '{key}' not found in values"
        return f"{values[key]:.2f}"

    def replace_expr(match):
        expr = match.group(1)
        result, error = evaluate_expression(expr, values)
        if error:
            return f"ERROR: {error}"
        return f"{result:.2f}"

    # Replace all {{key}} placeholders
    template = re.sub(r'\{\{(.*?)\}\}', replace_key, template)

    # Replace all [[expr]] placeholders
    template = re.sub(r'\[\[(.*?)\]\]', replace_expr, template)

    return template, None

def main():
    if len(sys.argv) != 3:
        print("Usage: python render_report.py TEMPLATE_PATH VALUES_PATH", file=sys.stderr)
        sys.exit(1)

    template_path = sys.argv[1]
    values_path = sys.argv[2]

    # Log setup
    log_file = "render.log"
    timestamp = datetime.now().isoformat() + "Z"[:-3]  # ISO 8601 with second precision
    logging.basicConfig(filename=log_file, mode='a', level=logging.INFO)

    # Validate JSON
    success, values = validate_json(values_path)
    if not success:
        print(f"ERROR: {success}", file=sys.stderr)
        logging.error(f"{timestamp} ERROR {success}")
        sys.exit(1)

    # Render template
    rendered, error = render_template(template_path, values)
    if error:
        print(f"ERROR: {error}", file=sys.stderr)
        logging.error(f"{timestamp} ERROR {error}")
        sys.exit(1)

    # Output rendered template
    print(rendered)

    # Log success
    logging.info(f"{timestamp} INFO rendered {template_path}")

if __name__ == "__main__":
    main()

import json
import sys
import os
import re
from datetime import datetime

def evaluate_expression(expr, values):
    try:
        # Replace variable names with their values
        for var in values:
            expr = expr.replace(var, str(values[var]))
        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, {})
    except Exception as e:
        raise ValueError(f"Invalid expression: {e}")

def render_template(template_path, values_path):
    try:
        with open(template_path, 'r', encoding='utf-8') as f:
            template = f.read()
    except IOError as e:
        raise RuntimeError(f"Failed to read template file: {e}")

    try:
        with open(values_path, 'r', encoding='utf-8') as f:
            values = json.load(f)
    except json.JSONDecodeError as e:
        raise RuntimeError(f"Invalid JSON in values file: {e}")
    except IOError as e:
        raise RuntimeError(f"Failed to read values file: {e}")

    if not isinstance(values, dict):
        raise RuntimeError("Values file must contain a JSON object")
    for value in values.values():
        if not isinstance(value, (int, float)):
            raise RuntimeError("All values in the JSON object must be numbers")

    def replace_placeholders(match):
        expr = match.group(1)
        try:
            result = evaluate_expression(expr, values)
            return f"{result:.2f}"
        except ValueError as e:
            raise RuntimeError(f"Invalid expression in placeholder: {e}")

    rendered = re.sub(r'\{\{([^}]+)\}\}', replace_placeholders, template)
    return rendered

def log_run(template_path, values_path, success):
    timestamp = datetime.now().isoformat()
    if success:
        log_message = f"{timestamp} INFO rendered {template_path}"
    else:
        log_message = f"{timestamp} ERROR failed to render"
    with open('render.log', 'a', encoding='utf-8') as f:
        f.write(log_message + '\n')

def main():
    if len(sys.argv) != 3:
        print("Usage: python render_report.py TEMPLATE_PATH VALUES_PATH", file=sys.stderr)
        sys.exit(1)

    template_path = sys.argv[1]
    values_path = sys.argv[2]

    try:
        rendered = render_template(template_path, values_path)
        print(rendered)
        log_run(template_path, values_path, True)
        sys.exit(0)
    except Exception as e:
        log_run(template_path, values_path, False)
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import json
import sys
import logging
from datetime import datetime
from typing import Dict, Any, Union

def render_template(template_path: str, values_path: str) -> str:
    with open(template_path, 'r', encoding='utf-8') as f:
        template = f.read()

    with open(values_path, 'r', encoding='utf-8') as f:
        values = json.load(f)

    rendered = []
    i = 0
    n = len(template)

    while i < n:
        if template.startswith('{{', i):
            j = template.find('}}', i)
            if j == -1:
                raise ValueError(f"Unclosed placeholder in template: {template[i:]}")
            expr = template[i+2:j]
            try:
                value = evaluate_expression(expr, values)
                rendered.append(f"{value:.2f}")
            except (ValueError, KeyError) as e:
                raise ValueError(f"Invalid expression or missing key: {expr}") from e
            i = j + 2
        else:
            rendered.append(template[i])
            i += 1

    return ''.join(rendered)

def evaluate_expression(expr: str, values: Dict[str, Union[int, float]]) -> float:
    try:
        # Replace variable names with their values
        for key in values:
            expr = expr.replace(key, str(values[key]))
        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, {})
    except (NameError, ZeroDivisionError, TypeError, ValueError) as e:
        raise ValueError(f"Invalid expression: {expr}") from e

def main():
    if len(sys.argv) != 3:
        print("Usage: python render_report.py TEMPLATE_PATH VALUES_PATH", file=sys.stderr)
        sys.exit(1)

    template_path = sys.argv[1]
    values_path = sys.argv[2]

    try:
        rendered = render_template(template_path, values_path)
        print(rendered)
        sys.exit(0)
    except Exception as e:
        timestamp = datetime.now().isoformat()
        log_entry = f"{timestamp} ERROR {str(e)}\n"
        with open('render.log', 'a', encoding='utf-8') as f:
            f.write(log_entry)
        sys.exit(1)

if __name__ == "__main__":
    main()

import json
import sys
import os
import re
from datetime import datetime
from typing import Dict, Any, Union

def evaluate_expression(expr: str, values: Dict[str, float]) -> Union[float, None]:
    try:
        # Replace variable names with their values
        for key in values:
            expr = expr.replace(key, str(values[key]))
        # Evaluate the expression safely
        return eval(expr)
    except (SyntaxError, NameError, ZeroDivisionError, TypeError):
        return None

def render_template(template_path: str, values_path: str) -> str:
    with open(template_path, 'r', encoding='utf-8') as template_file:
        template = template_file.read()

    with open(values_path, 'r', encoding='utf-8') as values_file:
        values = json.load(values_file)

    if not isinstance(values, dict):
        return None

    for key, value in values.items():
        if not isinstance(value, (int, float)):
            return None

    rendered = template
    placeholder_pattern = re.compile(r'\{\{(\w+)\}\}')

    for match in placeholder_pattern.finditer(template):
        expr = match.group(1)
        result = evaluate_expression(expr, values)
        if result is None:
            return None
        rendered = rendered.replace(match.group(0), f"{result:.2f}")

    return rendered

def log_to_file(message: str, log_path: str = 'render.log'):
    with open(log_path, 'a', encoding='utf-8') as log_file:
        log_file.write(f"{datetime.now().isoformat() + 'Z'} {message}\n")

def main():
    if len(sys.argv) != 3:
        log_to_file("ERROR Invalid arguments count")
        sys.exit(1)

    template_path = sys.argv[1]
    values_path = sys.argv[2]

    try:
        rendered = render_template(template_path, values_path)
        if rendered is None:
            log_to_file("ERROR Invalid template or values")
            sys.exit(1)
        print(rendered)
        log_to_file(f"INFO rendered {template_path}")
        sys.exit(0)
    except Exception as e:
        log_to_file(f"ERROR {str(e)}")
        sys.exit(1)

if __name__ == "__main__":
    main()
